<?php
declare(strict_types=1);
require_once __DIR__.'/../classes/GreenPortalDatabase.php';
require_once __DIR__.'/../classes/QuestionnaireService.php';
$env=GreenPortalDatabase::env();$u=GreenPortalDatabase::connect($env,'guniversal_dbp','GUNIVERSAL');$t=GreenPortalDatabase::connect($env,'gatlas_dbp','GPT');$code='TEST_ADMIN_P2_'.date('YmdHis').'_'.random_int(100,999);$questionnaire=0;$version=0;$question=0;$option=0;$result=['status'=>'ERRO','codigo'=>$code];
try{$service=new QuestionnaireService($t,$u);$draft=$service->createDraft(['codigo'=>$code,'nome_pt'=>'Teste administrativo P2','modulo'=>'TESTE','percentual_minimo'=>'70'],1);$questionnaire=(int)$draft['codquestionario'];$version=(int)$draft['codversao'];$question=$service->addQuestion($version,['codigo'=>'ACEITE','texto_pt'=>'Aceita?','tipo'=>'SIM_NAO','obrigatoria'=>'1'],1);$option=$service->addOption($question,['codigo'=>'SIM','rotulo_pt'=>'Sim','valor'=>'SIM','pontuacao'=>'1'],1);$builder=$service->builder($version);if(count($builder['perguntas'])!==1||count($builder['perguntas'][0]['opcoes'])!==1)throw new RuntimeException('Editor não carregou a pergunta/opção.');$published=$service->publish($version,1);$catalog=$service->catalog('TESTE');if(!array_filter($catalog,fn(array $row):bool=>(string)$row['codigo']===$code))throw new RuntimeException('Questionário publicado não apareceu no catálogo.');$result=['status'=>'CONCLUIDA','rascunho'=>'OK','perguntas'=>count($builder['perguntas']),'opcoes'=>count($builder['perguntas'][0]['opcoes']),'publicacao'=>$published];}
finally{if($option>0)$u->prepare('DELETE FROM amb_questionario_opcao WHERE codopcao=:id')->execute(['id'=>$option]);if($question>0)$u->prepare('DELETE FROM amb_questionario_pergunta WHERE codpergunta=:id')->execute(['id'=>$question]);if($version>0)$u->prepare('DELETE FROM amb_questionario_publicacao WHERE codversao=:id')->execute(['id'=>$version]);if($version>0)$u->prepare('DELETE FROM amb_questionario_versao WHERE codversao=:id')->execute(['id'=>$version]);if($questionnaire>0)$u->prepare('DELETE FROM amb_questionario WHERE codquestionario=:id')->execute(['id'=>$questionnaire]);$left=$u->prepare('SELECT COUNT(*) FROM amb_questionario WHERE codigo=:codigo');$left->execute(['codigo'=>$code]);$result['limpeza']=(int)$left->fetchColumn()===0?'OK':'FALHOU';echo json_encode($result,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT).PHP_EOL;}
